import { z } from "zod";

export const TitleSchema = z.string().trim().min(1).max(200);

export const TodoSchema = z
  .object({
    id: z.string().uuid(),
    title: TitleSchema,
    done: z.boolean(),
    createdAt: z.string().datetime(),
  })
  .strict();

export const TodoParamsSchema = z
  .object({
    id: z.string().uuid(),
  })
  .strict();

export const CreateTodoSchema = z
  .object({
    title: TitleSchema,
  })
  .strict();

export const UpdateTodoSchema = z
  .object({
    title: TitleSchema.optional(),
    done: z.boolean().optional(),
  })
  .strict()
  .refine((value) => value.title !== undefined || value.done !== undefined, {
    message: "At least one of title or done is required",
  });

export type Todo = z.infer<typeof TodoSchema>;
export type TodoParams = z.infer<typeof TodoParamsSchema>;
export type CreateTodo = z.infer<typeof CreateTodoSchema>;
export type UpdateTodo = z.infer<typeof UpdateTodoSchema>;

import type { ZodError } from "zod";

export interface HttpRequest {
  method: string;
  path: string;
  body?: unknown;
}

export interface HttpResponse {
  status: number;
  headers: Record<string, string>;
  body: unknown;
}

export interface ProblemFieldError {
  path: string;
  message: string;
}

export interface Problem {
  type: string;
  title: string;
  status: number;
  detail?: string;
  instance?: string;
  errors?: ProblemFieldError[];
}

export function json(status: number, body: unknown): HttpResponse {
  return { status, headers: { "content-type": "application/json" }, body };
}

export function noContent(): HttpResponse {
  return { status: 204, headers: {}, body: null };
}

export function problem(
  status: number,
  slug: string,
  title: string,
  options: { detail?: string; instance?: string; errors?: ProblemFieldError[]; headers?: Record<string, string> } = {},
): HttpResponse {
  const body: Problem = { type: `https://errors.example/${slug}`, title, status };
  if (options.detail !== undefined) body.detail = options.detail;
  if (options.instance !== undefined) body.instance = options.instance;
  if (options.errors !== undefined) body.errors = options.errors;
  return {
    status,
    headers: { ...(options.headers ?? {}), "content-type": "application/problem+json" },
    body,
  };
}

export function validationProblem(error: ZodError, instance: string, detail: string): HttpResponse {
  const errors: ProblemFieldError[] = error.issues.map((issue) => ({
    path: issue.path.length > 0 ? issue.path.map(String).join(".") : "(root)",
    message: issue.message,
  }));
  return problem(400, "validation-error", "Validation failed", { detail, instance, errors });
}

export function notFound(instance: string, detail: string): HttpResponse {
  return problem(404, "not-found", "Not Found", { detail, instance });
}

export function methodNotAllowed(instance: string, method: string, allowed: string[]): HttpResponse {
  return problem(405, "method-not-allowed", "Method Not Allowed", {
    detail: `Method ${method} is not allowed on ${instance}`,
    instance,
    headers: { allow: allowed.join(", ") },
  });
}

export function internalError(instance: string): HttpResponse {
  return problem(500, "internal-error", "Internal Server Error", {
    detail: "An unexpected error occurred",
    instance,
  });
}

import { db } from "../db";
import type { TodoRow } from "../db";
import { CreateTodoSchema, TodoParamsSchema, UpdateTodoSchema } from "../schemas";
import type { Todo } from "../schemas";
import { json, noContent, notFound, validationProblem } from "../http";
import type { HttpResponse } from "../http";

function toTodo(row: TodoRow): Todo {
  return { id: row.id, title: row.title, done: row.done, createdAt: row.createdAt };
}

function todoNotFound(instance: string, id: string): HttpResponse {
  return notFound(instance, `Todo ${id} was not found`);
}

export function listTodos(): HttpResponse {
  return json(200, db.todos.findMany().map(toTodo));
}

export function createTodo(body: unknown, instance: string): HttpResponse {
  const parsed = CreateTodoSchema.safeParse(body);
  if (!parsed.success) return validationProblem(parsed.error, instance, "Invalid request body");
  const row = db.todos.create({ title: parsed.data.title });
  const response = json(201, toTodo(row));
  response.headers["location"] = `/todos/${row.id}`;
  return response;
}

export function getTodo(rawId: string, instance: string): HttpResponse {
  const params = TodoParamsSchema.safeParse({ id: rawId });
  if (!params.success) return validationProblem(params.error, instance, "Invalid path parameter");
  const row = db.todos.findById(params.data.id);
  if (!row) return todoNotFound(instance, params.data.id);
  return json(200, toTodo(row));
}

export function updateTodo(rawId: string, body: unknown, instance: string): HttpResponse {
  const params = TodoParamsSchema.safeParse({ id: rawId });
  if (!params.success) return validationProblem(params.error, instance, "Invalid path parameter");
  const parsed = UpdateTodoSchema.safeParse(body);
  if (!parsed.success) return validationProblem(parsed.error, instance, "Invalid request body");
  const changes: { title?: string; done?: boolean } = {};
  if (parsed.data.title !== undefined) changes.title = parsed.data.title;
  if (parsed.data.done !== undefined) changes.done = parsed.data.done;
  const row = db.todos.update(params.data.id, changes);
  if (!row) return todoNotFound(instance, params.data.id);
  return json(200, toTodo(row));
}

export function deleteTodo(rawId: string, instance: string): HttpResponse {
  const params = TodoParamsSchema.safeParse({ id: rawId });
  if (!params.success) return validationProblem(params.error, instance, "Invalid path parameter");
  if (!db.todos.delete(params.data.id)) return todoNotFound(instance, params.data.id);
  return noContent();
}

import { internalError, methodNotAllowed, notFound } from "./http";
import type { HttpRequest, HttpResponse } from "./http";
import { createTodo, deleteTodo, getTodo, listTodos, updateTodo } from "./routes/todos";

function normalizePath(path: string): string {
  const withoutQuery = path.split("?")[0] ?? "";
  const trimmed = withoutQuery.length > 1 ? withoutQuery.replace(/\/+$/, "") : withoutQuery;
  return trimmed === "" ? "/" : trimmed;
}

function route(req: HttpRequest, path: string): HttpResponse {
  const method = req.method.toUpperCase();
  const segments = path.split("/").filter((segment) => segment.length > 0);
  const [resource, rawId, ...rest] = segments;

  if (resource !== "todos" || rest.length > 0) {
    return notFound(path, `No route matches ${path}`);
  }

  if (rawId === undefined) {
    if (method === "GET") return listTodos();
    if (method === "POST") return createTodo(req.body, path);
    return methodNotAllowed(path, method, ["GET", "POST"]);
  }

  const id = decodeURIComponent(rawId);
  if (method === "GET") return getTodo(id, path);
  if (method === "PATCH") return updateTodo(id, req.body, path);
  if (method === "DELETE") return deleteTodo(id, path);
  return methodNotAllowed(path, method, ["GET", "PATCH", "DELETE"]);
}

export async function handle(req: HttpRequest): Promise<HttpResponse> {
  const path = normalizePath(req.path);
  try {
    return route(req, path);
  } catch {
    return internalError(path);
  }
}
